-- My Scores — career catalogue seed (P4-CAR #55, piece 1; CAREER-008, OD-10).
--
-- Sent for review, not published: a reviewer checks each record in the admin
-- Careers tab and approves it (no author is recorded, so any admin can).
-- Careers: the 14 Academy Career Explorer careers (same slugs, English and
-- Lao text copied from src/data/careerPaths.ts and careerPathsLo.ts), with
-- proposed interest areas, clusters, related subjects, study length and work
-- settings (PRD §22.4), plus the five Lao pathway careers named in PRD §22.6.
-- The Explorer's salary and demand figures have no source yet, so they are not
-- entered as facts (OD-10). New Lao text needs the owner's review.
-- Institutions: names, websites and faculties read from each official
-- homepage on 2026-10-26 (English faculty names are translations).

insert into public.academic_career_content (kind, slug, draft, status, review_by, submitted_at)
select v.kind, v.slug, v.draft, 'in_review', public.academic_career_review_by(v.draft), now()
from (values
  ('career', 'software-engineer', '{"title_en":"Software Engineer","title_lo":"ວິສະວະກອນຊອບແວ","summary_en":"Design and build websites, mobile apps, business systems, and digital services.","summary_lo":"ອອກແບບ ແລະ ສ້າງເວັບໄຊ, ແອັບມືຖື, ລະບົບທຸລະກິດ ແລະ ບໍລິການດິຈິຕອນ.","preparation_en":["Strengthen mathematics and English","Study computing or a related major","Build 3–5 portfolio projects","Complete an internship","Apply for junior developer roles"],"preparation_lo":["ເສີມພື້ນຖານຄະນິດສາດ ແລະ ອັງກິດ","ຮຽນສາຂາຄອມພິວເຕີ ຫຼື ສາຂາທີ່ກ່ຽວຂ້ອງ","ສ້າງຜົນງານ 3–5 ໂຄງການ","ຝຶກງານໃນອົງກອນ","ສະໝັກວຽກນັກພັດທະນາລະດັບເລີ່ມຕົ້ນ"],"cluster":"technology","primary_area":"I","secondary_area":"A","related_subjects":["MATH","ICT","ENG"],"study_years":"4to5","work_settings":["office"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'data-analyst', '{"title_en":"Data Analyst","title_lo":"ນັກວິເຄາະຂໍ້ມູນ","summary_en":"Use data to explain performance, identify trends, and support better decisions.","summary_lo":"ນຳໃຊ້ຂໍ້ມູນເພື່ອອະທິບາຍຜົນງານ, ຊອກຫາແນວໂນ້ມ ແລະ ຊ່ວຍໃຫ້ຕັດສິນໃຈດີຂຶ້ນ.","preparation_en":["Build a foundation in statistics","Study analytics, economics, or computing","Learn Excel, SQL, and visualization","Publish a small data portfolio","Apply for analyst internships"],"preparation_lo":["ສ້າງພື້ນຖານສະຖິຕິ","ຮຽນການວິເຄາະ, ເສດຖະສາດ ຫຼື ຄອມພິວເຕີ","ຮຽນ Excel, SQL ແລະ ການສະແດງຂໍ້ມູນ","ສ້າງແຟ້ມຜົນງານຂໍ້ມູນ","ສະໝັກຝຶກງານດ້ານການວິເຄາະ"],"cluster":"technology","primary_area":"I","secondary_area":"C","related_subjects":["MATH","ICT","ENG"],"study_years":"4to5","work_settings":["office"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'civil-engineer', '{"title_en":"Civil Engineer","title_lo":"ວິສະວະກອນໂຍທາ","summary_en":"Plan and supervise roads, buildings, water systems, and public infrastructure.","summary_lo":"ວາງແຜນ ແລະ ຄວບຄຸມການກໍ່ສ້າງຖະໜົນ, ອາຄານ, ລະບົບນ້ຳ ແລະ ໂຄງລ່າງ.","preparation_en":["Focus on mathematics and physics","Earn an accredited engineering degree","Learn CAD and project tools","Complete supervised site experience","Pursue professional certification"],"preparation_lo":["ເນັ້ນຄະນິດສາດ ແລະ ຟີຊິກ","ຮຽນປະລິນຍາວິສະວະກຳທີ່ໄດ້ຮັບຮອງ","ຮຽນ CAD ແລະ ເຄື່ອງມືໂຄງການ","ເກັບປະສົບການໃນສະໜາມກໍ່ສ້າງ","ຂໍໃບຮັບຮອງວິຊາຊີບ"],"cluster":"engineering","primary_area":"R","secondary_area":"I","related_subjects":["MATH","PHYS"],"study_years":"4to5","work_settings":["outdoors","office"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'registered-nurse', '{"title_en":"Registered Nurse","title_lo":"ພະຍາບານວິຊາຊີບ","summary_en":"Provide patient care, health education, treatment support, and clinical coordination.","summary_lo":"ດູແລຄົນເຈັບ, ໃຫ້ຄວາມຮູ້ດ້ານສຸຂະພາບ ແລະ ຊ່ວຍໃນການປິ່ນປົວ.","preparation_en":["Study biology and chemistry","Complete an accredited nursing program","Finish clinical placements","Pass required licensing","Choose a hospital or community specialty"],"preparation_lo":["ຮຽນຊີວະວິທະຍາ ແລະ ເຄມີ","ຮຽນຫຼັກສູດພະຍາບານທີ່ໄດ້ຮັບຮອງ","ສຳເລັດການຝຶກຄລີນິກ","ຜ່ານການຂຶ້ນທະບຽນວິຊາຊີບ","ເລືອກສາຂາໂຮງໝໍ ຫຼື ຊຸມຊົນ"],"cluster":"health","primary_area":"S","secondary_area":"I","related_subjects":["BIO","CHEM"],"study_years":"4to5","work_settings":["with_people"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'digital-marketer', '{"title_en":"Digital Marketing Specialist","title_lo":"ຜູ້ຊ່ຽວຊານການຕະຫຼາດດິຈິຕອນ","summary_en":"Help organizations reach customers through content, campaigns, search, and social media.","summary_lo":"ຊ່ວຍອົງກອນເຂົ້າເຖິງລູກຄ້າຜ່ານເນື້ອຫາ, ໂຄສະນາ, ການຄົ້ນຫາ ແລະ ສື່ສັງຄົມ.","preparation_en":["Practice business writing and design","Study marketing or communications","Learn ad and analytics tools","Run a real or student campaign","Build a results-based portfolio"],"preparation_lo":["ຝຶກການຂຽນທຸລະກິດ ແລະ ການອອກແບບ","ຮຽນການຕະຫຼາດ ຫຼື ການສື່ສານ","ຮຽນເຄື່ອງມືໂຄສະນາ ແລະ ວິເຄາະ","ສ້າງແຄມເປນຈິງ","ສ້າງແຟ້ມຜົນງານທີ່ມີຜົນວັດແທກ"],"cluster":"business","primary_area":"E","secondary_area":"A","related_subjects":["ENG","ICT","LAO"],"study_years":"4to5","work_settings":["office"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'environmental-specialist', '{"title_en":"Environmental Specialist","title_lo":"ຜູ້ຊ່ຽວຊານສິ່ງແວດລ້ອມ","summary_en":"Assess environmental impact and help projects protect natural resources and communities.","summary_lo":"ປະເມີນຜົນກະທົບ ແລະ ຊ່ວຍໂຄງການປົກປ້ອງຊັບພະຍາກອນທຳມະຊາດ.","preparation_en":["Study biology, geography, and chemistry","Choose an environmental major","Learn GIS and field methods","Volunteer on a conservation project","Apply to consulting, government, or NGO roles"],"preparation_lo":["ຮຽນຊີວະວິທະຍາ, ພູມສາດ ແລະ ເຄມີ","ເລືອກສາຂາສິ່ງແວດລ້ອມ","ຮຽນ GIS ແລະ ວິທີການພາກສະໜາມ","ອາສາໃນໂຄງການອະນຸລັກ","ສະໝັກວຽກທີ່ປຶກສາ, ລັດ ຫຼື NGO"],"cluster":"environment_agriculture","primary_area":"R","secondary_area":"I","related_subjects":["BIO","CHEM","GEO"],"study_years":"4to5","work_settings":["outdoors","workshop_lab"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'accountant', '{"title_en":"Accountant","title_lo":"ນັກບັນຊີ","summary_en":"Record, review, and explain financial activity so organizations can operate responsibly.","summary_lo":"ບັນທຶກ, ກວດສອບ ແລະ ອະທິບາຍການເງິນເພື່ອໃຫ້ອົງກອນດຳເນີນງານຢ່າງຮັບຜິດຊອບ.","preparation_en":["Build strong mathematics habits","Study accounting or finance","Learn bookkeeping and spreadsheet tools","Complete an accounting internship","Work toward a recognized qualification"],"preparation_lo":["ສ້າງນິໄສຄະນິດສາດທີ່ດີ","ຮຽນບັນຊີ ຫຼື ການເງິນ","ຮຽນບັນຊີພື້ນຖານ ແລະ ຕາຕະລາງຄຳນວນ","ຝຶກງານບັນຊີ","ສຶກສາຕໍ່ໃບຮັບຮອງວິຊາຊີບ"],"cluster":"business","primary_area":"C","secondary_area":"E","related_subjects":["MATH"],"study_years":"4to5","work_settings":["office"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'ux-designer', '{"title_en":"UX/UI Designer","title_lo":"ນັກອອກແບບ UX/UI","summary_en":"Research user needs and design digital products that are clear, useful, and accessible.","summary_lo":"ຄົ້ນຄວ້າຄວາມຕ້ອງການຜູ້ໃຊ້ ແລະ ອອກແບບຜະລິດຕະພັນດິຈິຕອນທີ່ເຂົ້າໃຈງ່າຍ.","preparation_en":["Learn visual and interaction foundations","Study design, computing, or psychology","Master a prototyping tool","Create 3 detailed case studies","Apply for product design internships"],"preparation_lo":["ຮຽນພື້ນຖານພາບ ແລະ ປະຕິສຳພັນ","ຮຽນອອກແບບ, ຄອມພິວເຕີ ຫຼື ຈິດຕະວິທະຍາ","ຮຽນເຄື່ອງມືສ້າງຕົ້ນແບບ","ສ້າງ 3 ກໍລະນີສຶກສາ","ສະໝັກຝຶກງານອອກແບບຜະລິດຕະພັນ"],"cluster":"creative","primary_area":"A","secondary_area":"I","related_subjects":["ART","ICT","ENG"],"study_years":"4to5","work_settings":["office"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'ai-engineer', '{"title_en":"AI / Machine Learning Engineer","title_lo":"ວິສະວະກອນ AI / Machine Learning","summary_en":"Build, evaluate, and deploy machine-learning and generative-AI systems inside real products.","summary_lo":"ສ້າງ, ປະເມີນ ແລະ ນຳໃຊ້ລະບົບ Machine Learning ແລະ Generative AI ໃນຜະລິດຕະພັນ.","preparation_en":["Master programming and statistics","Study computing, AI, or data science","Build ML and LLM projects","Learn deployment and model evaluation","Apply for ML, applied AI, or research internships"],"preparation_lo":["ຊຳນານການຂຽນໂປຣແກຣມ ແລະ ສະຖິຕິ","ຮຽນຄອມພິວເຕີ, AI ຫຼື ຂໍ້ມູນ","ສ້າງໂຄງການ ML ແລະ LLM","ຮຽນການນຳໃຊ້ ແລະ ປະເມີນໂມເດວ","ສະໝັກຝຶກງານ AI ຫຼື ML"],"cluster":"technology","primary_area":"I","secondary_area":"C","related_subjects":["MATH","ICT","PHYS"],"study_years":"4to5","work_settings":["office","workshop_lab"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'ai-product-manager', '{"title_en":"AI Product Manager","title_lo":"ຜູ້ຈັດການຜະລິດຕະພັນ AI","summary_en":"Decide where AI creates genuine user value and guide teams from an idea to a responsible product.","summary_lo":"ກຳນົດບ່ອນທີ່ AI ສ້າງຄຸນຄ່າໃຫ້ຜູ້ໃຊ້ ແລະ ນຳພາທີມສ້າງຜະລິດຕະພັນຢ່າງຮັບຜິດຊອບ.","preparation_en":["Learn product and user-research basics","Build practical AI literacy","Lead a small AI product project","Practice evaluation and responsible-AI decisions","Enter through product, analyst, or technical roles"],"preparation_lo":["ຮຽນພື້ນຖານຜະລິດຕະພັນ ແລະ ຜູ້ໃຊ້","ສ້າງຄວາມເຂົ້າໃຈ AI","ນຳພາໂຄງການ AI ຂະໜາດນ້ອຍ","ຝຶກການປະເມີນ ແລະ AI ທີ່ຮັບຜິດຊອບ","ເລີ່ມຈາກວຽກຜະລິດຕະພັນ, ວິເຄາະ ຫຼື ເຕັກນິກ"],"cluster":"technology","primary_area":"E","secondary_area":"I","related_subjects":["ICT","ENG","MATH"],"study_years":"4to5","work_settings":["office","with_people"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'ai-governance-specialist', '{"title_en":"AI Governance Specialist","title_lo":"ຜູ້ຊ່ຽວຊານການກຳກັບ AI","summary_en":"Help organizations use AI legally, safely, transparently, and with clear human accountability.","summary_lo":"ຊ່ວຍອົງກອນນຳໃຊ້ AI ຢ່າງຖືກກົດໝາຍ, ປອດໄພ, ໂປ່ງໃສ ແລະ ມີຜູ້ຮັບຜິດຊອບ.","preparation_en":["Study law, policy, risk, or technology","Learn AI systems and data protection","Practice impact and risk assessments","Earn privacy, audit, or AI governance credentials","Apply to compliance, policy, or responsible-AI teams"],"preparation_lo":["ຮຽນກົດໝາຍ, ນະໂຍບາຍ, ຄວາມສ່ຽງ ຫຼື ເຕັກໂນໂລຊີ","ຮຽນລະບົບ AI ແລະ ການປົກປ້ອງຂໍ້ມູນ","ຝຶກປະເມີນຜົນກະທົບ ແລະ ຄວາມສ່ຽງ","ຮັບໃບຢັ້ງຢືນດ້ານຄວາມສ່ວນຕົວ ຫຼື AI","ສະໝັກທີມກຳກັບ, ນະໂຍບາຍ ຫຼື Responsible AI"],"cluster":"law_public","primary_area":"E","secondary_area":"C","related_subjects":["CIV","ICT","ENG"],"study_years":"4to5","work_settings":["office"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'conversation-designer', '{"title_en":"Conversation & Prompt Designer","title_lo":"ນັກອອກແບບບົດສົນທະນາ ແລະ Prompt","summary_en":"Design how people interact with AI assistants, including prompts, dialogue, tone, guardrails, and tests.","summary_lo":"ອອກແບບວິທີທີ່ຄົນສື່ສານກັບ AI ລວມທັງ prompt, ບົດສົນທະນາ, ນ້ຳສຽງ ແລະ ການທົດສອບ.","preparation_en":["Build strong writing and research skills","Study language, design, psychology, or computing","Learn LLM behavior and evaluation","Publish conversation-design case studies","Apply through UX writing, content design, or AI operations"],"preparation_lo":["ສ້າງທັກສະການຂຽນ ແລະ ຄົ້ນຄວ້າ","ຮຽນພາສາ, ອອກແບບ, ຈິດຕະວິທະຍາ ຫຼື ຄອມພິວເຕີ","ຮຽນພຶດຕິກຳ LLM ແລະ ການປະເມີນ","ສ້າງກໍລະນີສຶກສາບົດສົນທະນາ","ເລີ່ມຈາກ UX writing, content design ຫຼື AI operations"],"cluster":"creative","primary_area":"A","secondary_area":"S","related_subjects":["LAO","ENG","ICT"],"study_years":"4to5","work_settings":["office"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'ai-automation-specialist', '{"title_en":"AI Automation Specialist","title_lo":"ຜູ້ຊ່ຽວຊານ AI Automation","summary_en":"Redesign repetitive business work using AI agents, workflow tools, APIs, and human approval steps.","summary_lo":"ເຮັດໃຫ້ວຽກທີ່ຊ້ຳໆເຮັດໄດ້ອັດຕະໂນມັດ ດ້ວຍ AI agent, ເຄື່ອງມື workflow ແລະ API — ໂດຍມີຄົນກວດ ແລະ ອະນຸມັດ.","preparation_en":["Learn how business processes work","Study information systems or operations","Build automations with APIs and workflow tools","Document measurable project results","Apply to operations, consulting, or transformation teams"],"preparation_lo":["ຮຽນຂະບວນການທຸລະກິດ","ຮຽນລະບົບສາລະສົນເທດ ຫຼື ການດຳເນີນງານ","ສ້າງ automation ດ້ວຍ API ແລະ workflow tools","ບັນທຶກຜົນງານທີ່ວັດແທກໄດ້","ສະໝັກທີມດຳເນີນງານ, ທີ່ປຶກສາ ຫຼື ປ່ຽນແປງດິຈິຕອນ"],"cluster":"technology","primary_area":"C","secondary_area":"I","related_subjects":["ICT","MATH"],"study_years":"le3","work_settings":["office"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'ai-data-curator', '{"title_en":"AI Data & Evaluation Specialist","title_lo":"ຜູ້ຊ່ຽວຊານຂໍ້ມູນ ແລະ ການປະເມີນ AI","summary_en":"Create high-quality training and test data, evaluate AI responses, and find patterns in model failures.","summary_lo":"ສ້າງຂໍ້ມູນຝຶກ ແລະ ທົດສອບທີ່ມີຄຸນນະພາບ, ປະເມີນຄຳຕອບ AI ແລະ ຊອກຫາຈຸດຜິດພາດ.","preparation_en":["Develop strong language and analytical skills","Study data, language, or a specialist domain","Learn annotation and evaluation methods","Create an AI evaluation portfolio","Apply to model quality, data operations, or AI safety teams"],"preparation_lo":["ພັດທະນາພາສາ ແລະ ການວິເຄາະ","ຮຽນຂໍ້ມູນ, ພາສາ ຫຼື ສາຂາສະເພາະ","ຮຽນວິທີ annotation ແລະ evaluation","ສ້າງແຟ້ມຜົນງານປະເມີນ AI","ສະໝັກທີມຄຸນນະພາບໂມເດວ, ຂໍ້ມູນ ຫຼື AI safety"],"cluster":"technology","primary_area":"C","secondary_area":"I","related_subjects":["ICT","ENG"],"study_years":"le3","work_settings":["office"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'secondary-teacher', '{"title_en":"Secondary School Teacher","title_lo":"ຄູສອນມັດທະຍົມ","summary_en":"Plan lessons, teach a subject to secondary students and help each student make progress.","summary_lo":"ວາງແຜນບົດຮຽນ, ສອນວິຊາໃຫ້ນັກຮຽນມັດທະຍົມ ແລະ ຊ່ວຍໃຫ້ນັກຮຽນແຕ່ລະຄົນກ້າວໜ້າ.","preparation_en":["Keep strong marks in the subject you want to teach","Explain lessons to classmates","Study at a faculty of education","Complete a teaching practicum"],"preparation_lo":["ຮັກສາຄະແນນໃຫ້ດີໃນວິຊາທີ່ຢາກສອນ","ຝຶກອະທິບາຍບົດຮຽນໃຫ້ໝູ່","ຮຽນຢູ່ຄະນະສຶກສາສາດ","ຝຶກສອນຕົວຈິງ"],"cluster":"education","primary_area":"S","secondary_area":"I","related_subjects":["LAO","MATH"],"study_years":"4to5","work_settings":["with_people"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'agricultural-specialist', '{"title_en":"Agricultural Specialist","title_lo":"ນັກວິຊາການກະສິກຳ","summary_en":"Help farmers grow better crops and raise healthy animals using science and good practice.","summary_lo":"ຊ່ວຍຊາວກະສິກອນໃຫ້ປູກພືດໄດ້ດີຂຶ້ນ ແລະ ລ້ຽງສັດໃຫ້ແຂງແຮງ ໂດຍໃຊ້ວິທະຍາສາດ ແລະ ວິທີປະຕິບັດທີ່ດີ.","preparation_en":["Focus on biology and chemistry","Learn about farming in your area","Study at a faculty of agriculture","Do field work with farmers"],"preparation_lo":["ເນັ້ນວິຊາຊີວະສາດ ແລະ ເຄມີສາດ","ຮຽນຮູ້ກ່ຽວກັບການກະສິກຳໃນທ້ອງຖິ່ນ","ຮຽນຢູ່ຄະນະກະເສດສາດ","ລົງພາກສະໜາມກັບຊາວກະສິກອນ"],"cluster":"environment_agriculture","primary_area":"R","secondary_area":"I","related_subjects":["BIO","CHEM","GEO"],"study_years":"4to5","work_settings":["outdoors","workshop_lab"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'pharmacist', '{"title_en":"Pharmacist","title_lo":"ເພສັດຊະກອນ","summary_en":"Prepare and check medicines, and explain to patients how to use them safely.","summary_lo":"ກະກຽມ ແລະ ກວດກາຢາ, ແລະ ອະທິບາຍໃຫ້ຄົນເຈັບຮູ້ວິທີໃຊ້ຢາຢ່າງປອດໄພ.","preparation_en":["Focus on chemistry and biology","Practise careful, accurate work","Study pharmacy at a health sciences university","Complete supervised practice"],"preparation_lo":["ເນັ້ນວິຊາເຄມີສາດ ແລະ ຊີວະສາດ","ຝຶກເຮັດວຽກຢ່າງລະມັດລະວັງ ແລະ ຖືກຕ້ອງ","ຮຽນເພສັດສາດຢູ່ມະຫາວິທະຍາໄລວິທະຍາສາດສຸຂະພາບ","ຝຶກປະຕິບັດພາຍໃຕ້ການຊີ້ນຳ"],"cluster":"health","primary_area":"I","secondary_area":"S","related_subjects":["CHEM","BIO","MATH"],"study_years":"4to5","work_settings":["workshop_lab","with_people"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'lawyer', '{"title_en":"Lawyer","title_lo":"ທະນາຍຄວາມ","summary_en":"Advise people and organisations about the law and help them protect their rights.","summary_lo":"ໃຫ້ຄຳປຶກສາແກ່ບຸກຄົນ ແລະ ອົງກອນກ່ຽວກັບກົດໝາຍ ແລະ ຊ່ວຍປົກປ້ອງສິດຂອງເຂົາເຈົ້າ.","preparation_en":["Read widely and write clearly in Lao","Join debates or student councils","Study at a faculty of law","Complete legal training"],"preparation_lo":["ອ່ານຫຼາຍ ແລະ ຂຽນພາສາລາວໃຫ້ຈະແຈ້ງ","ເຂົ້າຮ່ວມການໂຕ້ວາທີ ຫຼື ສະພານັກຮຽນ","ຮຽນຢູ່ຄະນະນິຕິສາດ","ຝຶກອົບຮົມດ້ານກົດໝາຍ"],"cluster":"law_public","primary_area":"E","secondary_area":"S","related_subjects":["CIV","LAO","HIST"],"study_years":"4to5","work_settings":["office","with_people"],"editorial_priority":0,"facts":[]}'::jsonb),
  ('career', 'tourism-manager', '{"title_en":"Tourism Manager","title_lo":"ຜູ້ຈັດການດ້ານການທ່ອງທ່ຽວ","summary_en":"Plan trips and services for visitors, lead a team and look after guests.","summary_lo":"ວາງແຜນການເດີນທາງ ແລະ ບໍລິການໃຫ້ນັກທ່ອງທ່ຽວ, ນຳພາທີມງານ ແລະ ດູແລແຂກ.","preparation_en":["Practise English and another foreign language","Learn about places and culture in Laos","Study tourism or hospitality","Work part-time in tourism or a hotel"],"preparation_lo":["ຝຶກພາສາອັງກິດ ແລະ ພາສາຕ່າງປະເທດອື່ນ","ຮຽນຮູ້ສະຖານທີ່ ແລະ ວັດທະນະທຳຂອງລາວ","ຮຽນສາຂາການທ່ອງທ່ຽວ ຫຼື ການໂຮງແຮມ","ເຮັດວຽກນອກເວລາໃນທຸລະກິດທ່ອງທ່ຽວ ຫຼື ໂຮງແຮມ"],"cluster":"tourism_hospitality","primary_area":"E","secondary_area":"S","related_subjects":["ENG","GEO","LAO"],"study_years":"4to5","work_settings":["with_people","office"],"editorial_priority":0,"facts":[]}'::jsonb),
